-- Generated by scripts/backfill-rdl-titles.ts. Review, then run once in Supabase SQL Editor.
begin;

create temporary table rdl_title_backfill (
  material_id text primary key,
  old_title text not null,
  previous_title text not null,
  new_title text not null,
  action text not null check (action in ('KEEP_ORIGINAL', 'GENERATE_SHORT_TITLE')),
  english_word_count integer not null check (english_word_count between 1 and 5)
) on commit drop;


do $$
begin
  if (select count(*) from rdl_title_backfill) <> 86 then
    raise exception 'RDL title backfill must contain exactly 86 materials';
  end if;
  if exists (
    select 1 from rdl_title_backfill b
    left join reading_materials m on m.material_id = b.material_id
    where m.material_id is null or m.title not in (b.old_title, b.previous_title, b.new_title)
  ) then
    raise exception 'RDL title preflight failed: missing material or unexpected current title';
  end if;
end $$;

update reading_materials m
set title = b.new_title
from rdl_title_backfill b
where m.material_id = b.material_id
  and m.title is distinct from b.new_title;

update reading_logical_items i
set title = mapped.new_title
from (
  select distinct q.logical_item_id, b.new_title
  from reading_questions q
  join rdl_title_backfill b on b.material_id = q.material_id
) mapped
where i.logical_item_id = mapped.logical_item_id
  and i.module = 'rdl'
  and i.title is distinct from mapped.new_title;

do $$
begin
  if exists (
    select 1 from rdl_title_backfill b
    join reading_materials m on m.material_id = b.material_id
    where m.title <> b.new_title
  ) then
    raise exception 'RDL material title verification failed';
  end if;
  if exists (
    select 1 from reading_logical_items i
    join reading_questions q on q.logical_item_id = i.logical_item_id
    join reading_materials m on m.material_id = q.material_id
    where i.module = 'rdl' and i.title <> m.title
  ) then
    raise exception 'RDL logical item/material title verification failed';
  end if;
end $$;

commit;
